INSERT INTO cfg.indicator (id, name, unit, how_to_measure, why_it_matters, source_id, display_order) VALUES
  ('glucose', 'Blood glucose', 'mg/dL', 'With a glucometer or a continuous glucose monitor. A continuous monitor flew on Ax-4 in 2025.', 'Glucose is the sugar in your blood. A value outside the normal range can be a sign of abnormal glucose regulation.', 'inspiration4_metabolic_panel', 1),
  ('heart_rate', 'Heart rate', 'bpm', 'With a wearable ECG or a smartwatch, all day. On the ISS, the Bio-Monitor shirt does it.', 'How many times your heart beats each minute, hour by hour through the day.', 'lifesnaps', 2),
  ('resting_heart_rate', 'Resting heart rate', 'bpm', 'With a wearable ECG or a smartwatch, all day. On the ISS, the Bio-Monitor shirt does it.', 'Your heart rate when you are at rest. A resting heart rate that stays above your usual value can point to dehydration, infection, stress or a cardiovascular problem.', 'lifesnaps', 3),
  ('sleep_duration', 'Sleep duration', 'min', 'With a wrist tracker, every night. On the ISS, the Actiwatch does it.', 'How long you slept last night. Sleeping too little, night after night, is sleep deprivation.', 'lifesnaps', 4),
  ('sleep_efficiency', 'Sleep efficiency', '%', 'With a wrist tracker, every night. On the ISS, the Actiwatch does it.', 'The share of your time in bed that you spent asleep. A lower efficiency is a sign of reduced sleep quality.', 'lifesnaps', 5),
  ('skin_temperature', 'Skin temperature', '°C', 'With a wearable, every night. On the ISS, the Bio-Monitor shirt does it.', 'The temperature of your skin during the night. It is skin temperature, not core temperature. A raised temperature together with symptoms can point to an infection.', 'lifesnaps', 6),
  ('very_active_minutes', 'Very active minutes', 'min', 'With a wearable sensor, all day.', 'The minutes of the day you spent in intense activity. It is general activity, not resistance exercise, so it shows only in part whether you are keeping up with the exercise programme.', 'lifesnaps', 7),
  ('steps', 'Steps', 'steps', 'With a wearable sensor, all day.', 'The steps you took during the day. It is general activity, not resistance exercise, so it shows only in part whether you are keeping up with the exercise programme.', 'lifesnaps', 8),
  ('mood_happy', 'Happy', NULL, 'In the daily check-in on the tablet.', 'One of the six moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 9),
  ('mood_sad', 'Sad', NULL, 'In the daily check-in on the tablet.', 'One of the six moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 10),
  ('mood_tense', 'Tense or anxious', NULL, 'In the daily check-in on the tablet.', 'One of the six moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 11),
  ('mood_alert', 'Alert', NULL, 'In the daily check-in on the tablet.', 'One of the six moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 12),
  ('mood_rested', 'Rested or relaxed', NULL, 'In the daily check-in on the tablet.', 'One of the six moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 13),
  ('mood_neutral', 'Neutral', NULL, 'In the daily check-in on the tablet.', 'One of the six moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 14);
